mapper.select:
SELECT a.* FROM ( select s.id,s.name from survey_franchisee s left join survey_user_franchisee uf on s.id = uf.franchisee_id where s.delete_flag =0 and uf.delete_flag =0 and s.org_state = 0
and uf.user_id = #{userId,jdbcType=BIGINT}
and s.bus_type != 1
and s.bus_type != 2
) a

select GROUP_CONCAT(s.id)
from survey_franchisee s
where  s.delete_flag =0 and parent_id = #{id,jdbcType=BIGINT}

       	SELECT GROUP_CONCAT(id) FROM (
	SELECT id FROM survey_franchisee f WHERE id = #{surveyOrgId}

        UNION
        SELECT id FROM survey_franchisee f WHERE parent_id = #{surveyOrgId}

    ) b
